# SawBlade - Vertical disc spinner
# Keeps the front-facing disc at max RPM and charges the enemy.

WEAPON = "front"

def drive(me, enemy, arena):
    # Cannot drive while overturned, self-righting, or disabled
    if not me.can_drive or me.righting:
        return (0, 0)

    brg = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    # Keep the spinner (front) facing the enemy
    if abs(brg) > 12:
        t = 1.0 if brg > 0 else -1.0
        return (t, -t)

    # Close in; ease off at very short range for control
    if dist < 1.0:
        return (0.5, 0.5)
    return (1.0, 1.0)

