def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    rpm = 0.0
    w = me.weapons.get("front")
    if w and w["type"] == "spinner":
        rpm = abs(w["rpm"])
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    if rpm < 1500 and dist < 4.0:
        ax = me.x - enemy.x
        ay = me.y - enemy.y
        ar = hypot(ax, ay)
        if ar < 0.1:
            ax, ay = -1.0, 0.0
            ar = 1.0
        tx = me.x + (ax / ar) * 3.0
        ty = me.y + (ay / ar) * 3.0
        tr = hypot(tx, ty)
        if tr > 5.8:
            scale = 5.8 / tr
            tx *= scale
            ty *= scale
        b = bearing_to(tx, ty)
    else:
        h = radians(enemy.heading)
        fx = cos(h)
        fy = sin(h)
        ex = me.x - enemy.x
        ey = me.y - enemy.y
        cross = fx * ey - fy * ex
        lx = -sin(h)
        ly = cos(h)
        wl_x = enemy.x + (enemy.width / 2.0) * lx
        wl_y = enemy.y + (enemy.width / 2.0) * ly
        wr_x = enemy.x - (enemy.width / 2.0) * lx
        wr_y = enemy.y - (enemy.width / 2.0) * ly
        bx = enemy.x - (enemy.length / 2.0) * fx
        by = enemy.y - (enemy.length / 2.0) * fy
        if cross > 0:
            target_side = "left"
            tx, ty = wl_x, wl_y
        else:
            target_side = "right"
            tx, ty = wr_x, wr_y
        if target_side in enemy.wedges:
            if target_side == "left":
                tx, ty = wr_x, wr_y
            else:
                tx, ty = wl_x, wl_y
        dot = fx * ex + fy * ey
        if dot < -enemy.length / 2.0:
            if "back" in enemy.wedges:
                if cross > 0:
                    tx, ty = wl_x, wl_y
                else:
                    tx, ty = wr_x, wr_y
            else:
                tx, ty = bx, by
        tr = hypot(tx, ty)
        if tr > 5.8:
            scale = 5.8 / tr
            tx *= scale
            ty *= scale
        r = hypot(me.x, me.y)
        if r > 5.5:
            tx, ty = 0.0, 0.0
        b = bearing_to(tx, ty)
    e = b
    if abs(e) > 60:
        if e > 0:
            return (-1, 1)
        else:
            return (1, -1)
    if e >= 0:
        left = 1 - 2 * (e / 60.0)
        right = 1.0
    else:
        left = 1.0
        right = 1 - 2 * (-e / 60.0)
    if left > 1:
        left = 1
    if left < -1:
        left = -1
    if right > 1:
        right = 1
    if right < -1:
        right = -1
    if me.inverted:
        return (right, left)
    return (left, right)

