# SawBlade II - vertical disc spinner, reinforced rear
WEAPON = "front"
MAX_RPM = 2800

def drive(me, enemy, arena):
    if not me.can_drive or me.righting:
        return (0, 0)

    brg = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    my_rpm = 0.0
    if WEAPON in me.weapons:
        my_rpm = abs(me.weapons[WEAPON].get("rpm", 0))

    enemy_rpm = 0.0
    if "front" in enemy.weapons and enemy.weapons["front"].get("type") == "spinner":
        enemy_rpm = abs(enemy.weapons["front"].get("rpm", 0))

    # If the enemy spinner is fast and ours is not, back off to spin up safely.
    if my_rpm < 1800 and enemy_rpm > 1200:
        return (-0.7, -0.7)

    # Turn to face the enemy so the front spinner can bear.
    if abs(brg) > 15:
        t = 1.0 if brg > 0 else -1.0
        return (t, -t)

    # Low health: retreat.
    if me.health < 0.35:
        return (-0.6, -0.6)

    # Very close: ease off for control.
    if dist < 0.7:
        return (0.3, 0.3)

    return (1.0, 1.0)

