def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    r = hypot(me.x, me.y)
    w = me.weapons.get("front")
    rpm = 0.0
    if w and w.get("type") == "spinner":
        rpm = abs(w.get("rpm", 0.0))
    if r > 4.8:
        tx, ty = 0.0, 0.0
    else:
        if rpm < 1800 and dist < 3.0:
            if dist > 0.1:
                rx = me.x - (dx / dist) * 2.0
                ry = me.y - (dy / dist) * 2.0
            else:
                rx, ry = 0.0, 0.0
            rr = hypot(rx, ry)
            if rr > 4.5:
                rx *= 4.5 / rr
                ry *= 4.5 / rr
            tx, ty = rx, ry
        else:
            tx, ty = enemy.x, enemy.y
    tr = hypot(tx, ty)
    if tr > 4.8:
        scale = 4.8 / tr
        tx *= scale
        ty *= scale
    b = bearing_to(tx, ty)
    e = b
    if abs(e) > 60:
        if e > 0:
            left, right = -1.0, 1.0
        else:
            left, right = 1.0, -1.0
    else:
        if e >= 0:
            left = 1.0 - 2.0 * (e / 60.0)
            right = 1.0
        else:
            left = 1.0
            right = 1.0 - 2.0 * (-e / 60.0)
    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    if me.inverted:
        return (right, left)
    return (left, right)

