    if abs(brg) > 20:
        t = 1.0 if brg > 0 else -1.0
        return (t, -t)

    # Low health: retreat.
    if me.health < 0.35:
        return (-0.6, -0.6)

    # Very close: ease off for control.
    if dist < 0.6:
        return (0.4, 0.4)

    return (1.0, 1.0)

